// Leader colour palettes generated by scripts/civilopedia/colors.mjs
import colorData from "../data/leaderColors.json";

const PALETTE = colorData.palette || {};

const CIV_DEFAULTS = {};
for (const [fullName, palette] of Object.entries(PALETTE)) {
  if (!CIV_DEFAULTS[palette.civilization]) {
    CIV_DEFAULTS[palette.civilization] = { fullName, ...palette };
  }
}

/**
 * Full display name used as key in the palette manifest
 * @param {Object} leader - Leader object
 * @returns {string} "Name (Variant)" or "Name"
 */
export function getLeaderFullName(leader) {
  if (!leader) return "";
  return leader.variant
    ? `${leader.name} (${leader.variant})`
    : leader.name;
}

/**
 * Get the colour palette of a leader (the default jersey)
 * @param {Object} leader - Leader object with name/variant/civilization
 * @returns {Object|null} { primary, secondary, alternates, civilization }
 */
export function getLeaderPalette(leader) {
  if (!leader) return null;
  const fullName = getLeaderFullName(leader);
  if (PALETTE[fullName]) return PALETTE[fullName];
  if (PALETTE[leader.name]) return PALETTE[leader.name];
  return getCivPalette(leader.civilization);
}

/**
 * Get the default palette of a civilization
 * @param {string} civilization - Civilization name
 * @returns {Object|null} Palette
 */
export function getCivPalette(civilization) {
  if (!civilization) return null;
  return CIV_DEFAULTS[civilization] || null;
}

/**
 * Inline CSS custom properties for a palette
 * @param {Object|null} palette - Palette
 * @returns {Object} Style object
 */
export function paletteStyle(palette) {
  if (!palette) return {};
  return {
    "--leader-primary": palette.primary,
    "--leader-secondary": palette.secondary,
  };
}
